def solve(values):
    if not values or len(values) < 2:
        return 0
    max_sum = -float('inf')
    max_start = 0
    current_sum = 0
    for i in range(len(values)):
        current_sum += values[i]
        if i >= 1 and i - 1 < len(values) - 1:
            if current_sum > max_sum:
                max_sum = current_sum
                max_start = i - 1
    return max_start
```

